local function s(v) if type(v) == "table" then local t = {} for i, x in ipairs(v) do t[i] = s(x) end return "{" .. table.concat(t, ", ") .. "}" end if type(v) == "userdata" then local ok, r = pcall(function() return v.value end) if ok and r ~= nil and r ~= "" then return tostring(r) end end return tostring(v) end local function f(p) local ok, v = pcall(function() return TweakDB:GetFlat(p) end) if ok and v ~= nil then return s(v) end return "nil" end local function P(x) print("[SDP] " .. x) end for _, k in ipairs({"storyModeMultiplier", "easyModeMultiplier", "normalModeMultiplier", "hardModeMultiplier", "coverVsNormalWeaponsMultiplier", "coverVsSmartWeaponsMultiplier", "HMGGroupMultiplier"}) do P("TimeBetweenHits." .. k .. " = " .. f("TimeBetweenHits." .. k)) end for _, k in ipairs({"missShotOffset.defaultSpreadAngle", "missShotOffset.specialSpreadAngle", "missShotOffset.minimumDistanceAroundTarget", "missShotOffset.additionalSpreadRandZOffset"}) do P("TimeBetweenHits." .. k .. " = " .. f("TimeBetweenHits." .. k)) end for _, t in ipairs({"Melee", "MeleeApproach", "QuickMelee", "CatchUp", "CatchUpEasy", "CatchUpHard", "CloseRing", "MeleeRing", "MediumRing", "FarRing", "Quickhack", "GrenadeThrow", "GrenadeThrow_Hard", "Peek", "Strafe", "StrafeEvade", "Dodge", "Block", "TakeCover", "Charge", "Sync", "Equip"}) do local id = "Tickets." .. t P(id .. ": max=" .. f(id .. ".maxNumberOfTickets") .. " min=" .. f(id .. ".minNumberOfTickets") .. " pct=" .. f(id .. ".percentageNumberOfTickets") .. " cooldowns=" .. f(id .. ".cooldowns")) end for _, id in ipairs({"Tickets.CatchUp_inline0.duration", "Tickets.Melee_inline0.duration", "Tickets.Quickhack_inline0.duration", "Tickets.GrenadeThrow_inline0.duration", "Tickets.Strafe_inline0.duration", "MovementActions.StrafeCooldown.duration", "SpecialActions.CombatStimCooldown.duration", "SpecialActions.CombatStimCooldown_Hard.duration", "SpecialActions.CombatStimCooldown_VeryHard.duration", "AIQuickHack.AIQuickHack_inline4.duration", "Items.Base_NPC_SmartGun_Stats_inline0.value", "Items.Base_NPC_SmartGun_Stats_inline1.value"}) do P(id .. " = " .. f(id)) end local ok, recs = pcall(function() return TweakDB:GetRecords("gamedataAIPatternDelay_Record") end) if ok and recs then local n, sum, mn, mx, zero = 0, 0, 1e9, -1e9, 0 for _, r in ipairs(recs) do local okI, id = pcall(function() return r:GetID().value end) if okI and id then local okD, d = pcall(function() return TweakDB:GetFlat(id .. ".delay") end) if okD and type(d) == "number" then n = n + 1 sum = sum + d if d < mn then mn = d end if d > mx then mx = d end if d == 0 then zero = zero + 1 end end end end if n > 0 then P(("AIPatternDelay: n=%d min=%.3f mean=%.3f max=%.3f zeros=%d"):format(n, mn, sum / n, mx, zero)) else P("AIPatternDelay: no numeric delays read") end else P("AIPatternDelay: type not found") end for _, ty in ipairs({"gamedataThreatTrackingPresetBase_Record", "gamedataThreatTrackingPreset_Record", "gamedataSenses_Record", "gamedataSenseObjectType_Record"}) do local okT, rr = pcall(function() return TweakDB:GetRecords(ty) end) P(ty .. ": " .. ((okT and rr) and tostring(#rr) or "unknown type")) end P("done")
